import re
from fractions import Fraction

_NUM = r"(\d+(?:\.\d*)?|\.\d+)"

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_COMPONENT_RE = re.compile(r"\s*" + _NUM + r"\s*([A-Za-z]+)\s*")
_ISO_RE = re.compile(
    r"P(?:" + _NUM + r"W)?(?:" + _NUM + r"D)?"
    r"(?:T(?:" + _NUM + r"H)?(?:" + _NUM + r"M)?(?:" + _NUM + r"S)?)?"
)
_INT_RE = re.compile(r"\d+")


def _to_seconds(total: Fraction) -> int:
    # Round to nearest whole second, halves rounding up.
    return int((total + Fraction(1, 2)).__floor__())


def _frac(s: str) -> Fraction:
    return Fraction(s)


def _parse_clock(text: str) -> int:
    parts = text.split(":")
    if len(parts) not in (2, 3):
        raise ValueError(f"invalid clock duration: {text!r}")
    for p in parts:
        if not re.fullmatch(r"\d+(?:\.\d+)?", p):
            raise ValueError(f"invalid clock duration: {text!r}")
    values = [_frac(p) for p in parts]
    if len(values) == 2:
        mins, secs = values
        hours = Fraction(0)
    else:
        hours, mins, secs = values
    if mins >= 60 or secs >= 60:
        raise ValueError(f"invalid clock duration: {text!r}")
    return _to_seconds(hours * 3600 + mins * 60 + secs)


def _parse_iso(text: str) -> int:
    m = _ISO_RE.fullmatch(text)
    if not m or text == "P" or text.endswith("T"):
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    weeks, days, hours, minutes, seconds = m.groups()
    total = Fraction(0)
    for val, mult in (
        (weeks, 604800), (days, 86400), (hours, 3600), (minutes, 60), (seconds, 1)
    ):
        if val is not None:
            total += _frac(val) * mult
    return _to_seconds(total)


def _parse_components(text: str) -> int:
    pos = 0
    total = Fraction(0)
    found = False
    while pos < len(text):
        m = _COMPONENT_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += _frac(m.group(1)) * _UNITS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _to_seconds(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")
    if _INT_RE.fullmatch(s):
        return int(s)
    if ":" in s:
        return _parse_clock(s)
    if s.startswith("P") or s.startswith("p"):
        return _parse_iso(s.upper())
    if s.startswith("-") or s.startswith("+"):
        raise ValueError(f"negative or signed duration: {text!r}")
    return _parse_components(s)

